command:
$ErrorActionPreference="Stop"
Write-Host "REMOVABLE_PROBE_BEGIN"
Get-CimInstance Win32_LogicalDisk | Sort-Object DeviceID | ForEach-Object {
  Write-Host ("LOGICAL_DISK DeviceID={0} DriveType={1} FileSystem={2} VolumeName={3}" -f $_.DeviceID,$_.DriveType,$_.FileSystem,$_.VolumeName)
}
Get-Volume | Sort-Object DriveLetter | ForEach-Object {
  Write-Host ("VOLUME DriveLetter={0} DriveType={1} FileSystemType={2} Health={3}" -f $_.DriveLetter,$_.DriveType,$_.FileSystemType,$_.HealthStatus)
}
Write-Host "REMOVABLE_PROBE_END"
